+117|  const buildSectorCenters = (sectors) => {
+118|    const R = 140;
+119|    const centers = new Map();
+120|    const ordered = sectors.slice().sort(d3.ascending);
+121|    ordered.forEach((s, i) => {
+122|      const angle = (2 * Math.PI * i) / ordered.length - Math.PI / 2;
+123|      centers.set(s, {
+124|        x: cx + R * Math.cos(angle),
+125|        y: cy + R * Math.sin(angle),
+126|      });
+127|    });
+128|    return centers;
+129|  };
