+134|
+135|    const sectors = Array.from(new Set(data.map((d) => d.sector))).sort(d3.ascending);
+136|    const color = buildSectorPalette(sectors);
+137|    const sectorCenters = buildSectorCenters(sectors);
+138|
+139|    const capValues = data
+140|      .filter((d) => !d.isETF && d.marketCap != null && !Number.isNaN(d.marketCap))
+141|      .map((d) => d.marketCap);
+142|
+143|    const capExtent = d3.extent(capValues);
+144|    const radiusScale = d3
+145|      .scaleSqrt()
+146|      .domain([capExtent[0] ?? 0, capExtent[1] ?? 1])
+147|      .range([14, 46]);
+148|
+149|    const ETF_R = 18;
