+153|      const sc = sectorCenters.get(d.sector) ?? { x: cx, y: cy };
+154|
+155|      const jitterX = (hashUnit(d.ticker, 'x') - 0.5) * 60;
+156|      const jitterY = (hashUnit(d.ticker, 'y') - 0.5) * 60;
+157|
+158|      return {
+159|        ...d,
+160|        r,
+161|        x: sc.x + jitterX,
+162|        y: sc.y + jitterY,
+163|      };
